// @pit: {"label": "Format check and open PR for audit ignore list"}
async ({ delivery: { format, listChangedFiles, openPullRequest } }) => {
  const f = await format({ checkOnly: true });
  if (!f.formatted) return f as unknown as PitJsonValue;
  const files = (await listChangedFiles({ includeDeleted: true })).files;
  return (await openPullRequest({
    branch: "fix/411-ignore-withdrawn-advisory",
    files,
    message: "ci: ignore withdrawn picomatch advisory in runtime audit

GHSA-fc5q-39xc-vjpf was withdrawn, but npm audit still reported it and
failed CI. npm audit has no ignore list, so CI and the Release workflow now
run scripts/audit-runtime.ts, which skips listed advisories (each with a
reason) and the packages vulnerable only through them.

Closes #411",
    title: "Ignore withdrawn picomatch advisory in the runtime audit (#411)",
    body: "GHSA-fc5q-39xc-vjpf was withdrawn, but `npm audit --omit=dev` still reported picomatch (and fdir/tinyglobby through it), failing CI on every open PR.

- `scripts/audit-runtime.ts` (`npm run audit:runtime`) runs `npm audit --omit=dev --json`, removes advisories listed in `IGNORED` with their reason, then removes packages vulnerable only through them. Any other advisory still fails.
- CI and Release workflows use it; `docs/releasing.md` documents it.
- Tests: `test/process/audit-runtime.test.ts`.

Closes #411",
  })) as unknown as PitJsonValue;
}
